    def test_planner_review_of_the_refresh_is_refused_at_enqueue_proposal(self):
        tasks, _ = self.done_refresh()
        r = self.runner()
        r.state["tasks"]["ref-1"] = tasks["ref-1"]
        raw = self.review_task(tasks) | {"id": "pp-rev", "prompt": "review", "title": "r"}
        raw.pop("status")
