        raw = {k: v for k, v in self.rpraw().items() if k not in ("verify_cmd",)} | {"title": "p"}
        with self.assertRaisesRegex(ValueError, "owner CLI"):
            r.enqueue_proposal(raw)
        self.assertNotIn(self.REP, r.state["tasks"])

