    def test_state_that_is_not_an_object_is_refused_by_the_preflight(self):
        (self.home / "state.json").write_bytes(b"[]")
        self.write_prewrite()
        with self.assertRaises(R.GateError):
            R.transfer_preflight(self.cfg, rlock_held=True, wlock_held=True)

    def test_missing_files_and_missing_checkpoint_are_refused(self):
        for name in (R.D16_BOOT_ACTIVATION_NAME, R.S0_D16_QLED_NAME, "events.jsonl", "state.json"):
            with self.subTest(name):
                self.rebuild()
                (self.home / name).unlink()
                self.assert_refused()
        self.rebuild()
        shutil.rmtree(self.home / R.TRANSFER_CHECKPOINT)
        self.assert_refused("authorization-prewrite.json is missing")
        self.rebuild()
        (self.home / R.TRANSFER_CHECKPOINT / R.TRANSFER_PREWRITE).write_text("{truncated")
        self.assert_refused("malformed")
        self.rebuild()
        pw = json.loads((self.home / R.TRANSFER_CHECKPOINT / R.TRANSFER_PREWRITE).read_text())
        pw["head"] = "1" * 40
        (self.home / R.TRANSFER_CHECKPOINT / R.TRANSFER_PREWRITE).write_text(json.dumps(pw))
        self.pin_prewrite()  # a coherently re-pinned fixture still must not contradict the pinned incident
        self.assert_refused("contradicts")

    def test_prewrite_inventory_is_pinned_to_the_reviewed_hash(self):
        pinned = "288cc8b2bb2b11e439ea3310b5e8757b708cc2f9de1b44cdf49d8f27ab43e4ac"  # the fixture patches the constant
        self.assertIn(f'TRANSFER_PREWRITE_SHA = "{pinned}"', Path(R.__file__).read_text())
        path = self.home / R.TRANSFER_CHECKPOINT / R.TRANSFER_PREWRITE
        # the inventory and the old evidence are coherently tampered, but the pinned hash is not changed
        self.mutate_state(lambda st: st["tasks"].update({"extra": {"id": "extra", "status": "DONE"}}))
        self.write_prewrite()  # coherent new inventory; the fixture re-pins, so undo that re-pin
        self.assertNotEqual(hashlib.sha256(path.read_bytes()).hexdigest(), pinned)
        with mock.patch.object(R, "TRANSFER_PREWRITE_SHA", pinned):
            with self.assertRaises(R.GateError) as cm:
                R.transfer_preflight(self.cfg, rlock_held=True, wlock_held=True)
            self.assertIn("pinned inventory", str(cm.exception))
            r = self.boot()
            self.assertIsNone(self.record(), "a tampered inventory must consume nothing")
            self.assertEqual(R.quarantine_state(self.cfg)[0], R._QS_DENY)
        raw = path.read_bytes()
        path.write_bytes(raw + b" ")  # a single byte change to the pinned inventory itself
        self.assert_refused("pinned inventory")

    def test_event_log_corruption_ambiguity_and_prior_transfer_events_are_refused(self):
        def append(obj):
            (self.home / "events.jsonl").write_bytes(self.raw("events.jsonl") + json.dumps(obj).encode() + b"\n")
        entered = {"kind": "s0-d16-quarantine-entered", "pid": self.old_pid, "boot_nonce": self.old_nonce,
                   "code_sha256": self.old_sha}
        cases = {
            "malformed line": lambda: (self.home / "events.jsonl").write_bytes(self.raw("events.jsonl") + b"{oops\n"),
            "partial last line": lambda: (self.home / "events.jsonl").write_bytes(self.raw("events.jsonl") + b'{"kind"'),
            "non-object line": lambda: (self.home / "events.jsonl").write_bytes(self.raw("events.jsonl") + b"[1]\n"),
            "duplicate entered": lambda: append(entered),
            "activation failed": lambda: append({"kind": "s0-d16-quarantine-activation-failed"}),
            "prior transfer event": lambda: append({"kind": "quarantine-transfer-stage", "transition_id": "a" * 32,
                                                    "stage": "TRANSFER_CONSUMED"}),
        }
        for name, mutate in cases.items():
            with self.subTest(name):
                self.rebuild()
                mutate()
                self.assert_refused()
        self.rebuild()  # the entered event binds a different nonce / is absent / lies beyond the pre-write prefix
        self.write_home(ledger={"code_sha256": self.old_sha, "dual_rebind_consumed": False, "entered_at": "t",
                                "runner_boot_nonce": "cd" * 16, "runner_pid": self.old_pid, "schema": 1})
        self.assert_refused("does not bind")
        self.rebuild()
        evt = self.raw("events.jsonl")
        (self.home / "events.jsonl").write_bytes(b"\n".join(x for x in evt.split(b"\n") if b"quarantine-entered" not in x))
        self.write_prewrite()
        self.assert_refused("exactly one")

    def test_state_must_bind_the_old_runner_and_prove_the_slot_unused_by_absence(self):
        cases = {
            "wrong runner block": lambda st: st["runner"].update(boot_nonce="ee" * 16),
            "old code hash": lambda st: st["runner"].update(code_sha256="5" * 64),
            "slot task exists": lambda st: st["tasks"].update({R.S0_DUAL_REBIND_ID: {"id": R.S0_DUAL_REBIND_ID}}),
            "slot review exists": lambda st: st["tasks"].update(
                {"rv-x": {"id": "rv-x", "role": "code-review", "review_of": {"task_id": R.S0_DUAL_REBIND_ID}}}),
            "open handoff": lambda st: st.update(handoff={"request": {"id": "h"}}),
            "handoff quarantine": lambda st: st.update(handoff={"request": None, "quarantine": "late turn"}),
            "worker running": lambda st: st["tasks"]["hist-write"].update(status="RUNNING"),
        }
        for name, fn in cases.items():
            with self.subTest(name):
                self.rebuild()
                self.mutate_state(fn)  # after the real review, which saves the successor's own runner block
                self.assert_refused()

