    # ---- replay, duplicate writers, PID reuse -------------------------------
    def test_record_writer_refuses_replay_regression_and_immutable_changes(self):
        self.boot()
        rec = self.record()
        with self.assertRaises(R.GateError):
            R._transition_write(self.cfg, rec, create=True)  # a spent transfer is never minted twice
        for name, bad in {"stage regression": {**rec, "stage": "TRANSFER_CONSUMED"},
                          "stage skip": {**rec, "stage": "ACTIVE"},
                          "immutable pre-image": {**rec, "pre_image": {**rec["pre_image"], "digest": "f" * 64}},
                          "new commit": {**rec, "new": {**rec["new"], "commit": "a" * 40}},
                          "restart un-spent": {**rec, "boot_epoch": 2, "restart_used": True}, }.items():
            with self.subTest(name):
                if name == "restart un-spent":
                    R._transition_write(self.cfg, bad)
                    with self.assertRaises(R.GateError):
                        R._transition_write(self.cfg, {**bad, "restart_used": False})
                    continue
                with self.assertRaises(R.GateError):
                    R._transition_write(self.cfg, bad)

    def test_replayed_old_record_bytes_are_denied_after_stage_or_slot_progress(self):
        self.boot()
        s0_unused = self.raw(R.TRANSFER_RECORD_NAME)
        r = self.consume_slot()
        s0_consumed = self.raw(R.TRANSFER_RECORD_NAME)
        # replay the S0_REBIND/UNUSED bytes to hand the slot out again
        (self.home / R.TRANSFER_RECORD_NAME).write_bytes(s0_unused)
        self.assertIn("replayed", R._transition_bound_problem(self.cfg, self.record(), full=True))
        r.wlock.acquire({"pid": os.getpid()})
        try:
            with self.assertRaises(R.GateError):
                r._transition_consume_slot(self.lane_task())
        finally:
            r.wlock.release()
        before = self.raw(R.TRANSFER_RECORD_NAME)
        self.boot(nonce="n2" * 16)
        self.assertEqual(self.raw(R.TRANSFER_RECORD_NAME), before)
        (self.home / R.TRANSFER_RECORD_NAME).write_bytes(s0_consumed)

    def test_replayed_earlier_stage_record_is_denied(self):
        self.ci_ok[self.succ_commit] = False
        self.boot()
        consumed_bytes = self.raw(R.TRANSFER_RECORD_NAME)
        self.ci_ok[self.succ_commit] = True
        self.boot(nonce="n2" * 16)
        self.assertEqual(self.record()["stage"], "S0_REBIND")
        (self.home / R.TRANSFER_RECORD_NAME).write_bytes(consumed_bytes)  # rewind to TRANSFER_CONSUMED
        self.assertIn("behind its audit trail", R._transition_bound_problem(self.cfg, self.record(), full=True))
        calls = len(self.ci_calls)
        self.boot(nonce="n3" * 16)
        self.assertEqual(self.raw(R.TRANSFER_RECORD_NAME), consumed_bytes)
        self.assertEqual(len(self.ci_calls), calls)

    def test_duplicate_writer_is_denied_at_every_record_boundary(self):
        holder = R.FileLock(R.writer_lock_path(self.cfg.home, self.cfg.repo))
        self.assertTrue(holder.acquire({"pid": os.getpid(), "who": "other writer"}))
        try:
            self.boot()
            self.assertIsNone(self.record())
            self.assertEqual(self.pre_images(), [])
            self.assertTrue(self.reasons("quarantine-transfer-refused"))
        finally:
            holder.release()
        self.boot()  # the SAME process retries after the lock cleared: not a restart
        self.assertEqual(self.record()["stage"], "S0_REBIND")
        holder = R.FileLock(R.writer_lock_path(self.cfg.home, self.cfg.repo))
        self.assertTrue(holder.acquire({"pid": os.getpid(), "who": "other writer"}))
        try:
            before = self.raw(R.TRANSFER_RECORD_NAME)
            self.boot(nonce="n3" * 16)  # a re-attestation needs the writer lock
            self.assertEqual(self.raw(R.TRANSFER_RECORD_NAME), before)
        finally:
            holder.release()

