    # ---- VERIFIED / ACTIVE and permanent denials -----------------------------
    def test_s0_product_and_d16_dual_version_are_denied_before_and_at_every_stage(self):
        base = {**self.ordinary_task(), "module": R.S0_MODULE}
        d16, s0_product = {**base, "id": R.D16_DUAL_ID}, {**base, "id": "s0-product", "plan_phase": R.S0_MARKER}
        self.ci_ok[self.succ_commit] = False
        self.boot()
        for t in (d16, s0_product):  # TRANSFER_CONSUMED
            self.assertIn("DENIED", self.gate(t))
        self.ci_ok[self.succ_commit] = True
        self.boot(nonce="n2" * 16)  # S0_REBIND
        self.assertEqual(self.record()["stage"], "S0_REBIND")
        for t in (d16, s0_product):
            self.assertIn("DENIED", self.gate(t))

    def test_active_transfer_still_denies_s0_product_and_the_d16_dual_version_id(self):
        base = {**self.ordinary_task(), "module": R.S0_MODULE}
        d16 = {**base, "id": R.D16_DUAL_ID}
        s0_product = {**base, "id": "s0-product", "plan_phase": R.S0_MARKER}
        r, head = self.drive_to_active()
        rec = self.record()
        self.assertEqual(rec["stage"], "ACTIVE", self.reasons("quarantine-transfer-probe-failed"))
        self.assertEqual(rec["verified"]["commit"], head)
        self.assertEqual(self.stage_events(), ["TRANSFER_CONSUMED", "S0_REBIND", "VERIFIED", "ACTIVE"])
        self.assertEqual(R._transition_mode(self.cfg)[0], "ACTIVE")
        self.assertEqual(R.quarantine_state(self.cfg)[0], R._QS_ACTIVE)
        self.assertIn("D16_DUAL_DENIED", self.gate(d16))
        self.assertIn("S0_PRODUCT_DENIED", self.gate(s0_product))
        remediation = {**base, "id": "d16-fix", "role": "implement", "remediation_of": R.D16_DUAL_ID}
        self.assertIn("D16_DUAL_DENIED", self.gate(remediation))
        self.assertIn("CLOSED", self.gate(self.lane_task()))  # the fixed rebind lane is spent
        # a later process is denied: no restart is permitted once the S0 slot consumption is persisted
        before, events = self.raw(R.TRANSFER_RECORD_NAME), self.stage_events()
        self.boot(nonce="n2" * 16)
        self.assertEqual(self.raw(R.TRANSFER_RECORD_NAME), before)
        rec2 = self.record()
        self.assertEqual((rec2["stage"], rec2["transition_id"], rec2["boot_epoch"], rec2["restart_used"]),
                         ("ACTIVE", rec["transition_id"], rec["boot_epoch"], rec["restart_used"]))
        self.assertEqual(self.stage_events(), events)
        self.assertTrue(any("S0 slot consumption" in (x or "") for x in self.reasons("quarantine-transfer-denied")))
        self.assertIn("D16_DUAL_DENIED", self.gate(d16))
        self.assertEqual(R._transition_mode(self.cfg)[0], "HOLD")  # the new process never became the attested runner

    def assert_all_ingress_refused(self, label):
        """Read-only quarantine_state, gate_reason and enqueue must all fail closed; nothing is queued."""
        qs = R.quarantine_state(self.cfg)[0]
        self.assertIn(qs, (R._QS_DENY, R._QS_RESTARTED), label)
        self.assertIn("TRANSFER_HOLD", self.gate(self.ordinary_task()), label)
        queued = list((self.home / "queue").glob("*.json"))
        with self.assertRaises(ValueError) as cm:
            R.enqueue(self.cfg, {k: v for k, v in self.ordinary_task().items() if k not in ("status", "attempts")})
        self.assertIn("enqueue refused", str(cm.exception), label)
        self.assertEqual(list((self.home / "queue").glob("*.json")), queued, label)

    def test_active_admission_rechecks_preserved_bytes_and_audit_replay_every_time(self):
        r, _ = self.drive_to_active()
        self.assertEqual(R._transition_mode(self.cfg)[0], "ACTIVE")
        self.assertEqual(self.gate(self.ordinary_task()), None)
        pre = self.home / self.record()["pre_image"]["dir"]
        keep = (pre / "boot-token.json").read_bytes()
        (pre / "boot-token.json").write_bytes(keep + b" ")  # manifest untouched: only the full check sees it
        self.assertEqual(R._transition_mode(self.cfg)[0], "HOLD")
        self.assert_all_ingress_refused("altered preserved file")
        (pre / "boot-token.json").write_bytes(keep)  # restored bytes are re-trusted only by re-verification
        self.assertEqual(R._transition_mode(self.cfg)[0], "ACTIVE")
        active_bytes = self.raw(R.TRANSFER_RECORD_NAME)
        rec = self.record()
        self.rewrite_record(stage="S0_REBIND")  # rolled back behind the audit trail
        self.assert_all_ingress_refused("record rolled back after ACTIVE")
        (self.home / R.TRANSFER_RECORD_NAME).write_bytes(active_bytes)
        self.assertEqual(R._transition_mode(self.cfg)[0], "ACTIVE")
        self.assertEqual(self.record()["stage"], rec["stage"])

    def test_s0_rebind_admission_rechecks_preserved_bytes_and_audit_replay(self):
        self.boot()
        self.consume_slot()
        self.assertEqual(R._transition_mode(self.cfg)[0], "LANE")
        s0_consumed = self.raw(R.TRANSFER_RECORD_NAME)
        pre = self.home / self.record()["pre_image"]["dir"]
        keep = (pre / "state.json").read_bytes()
        (pre / "state.json").write_bytes(keep + b" ")
        self.assertEqual(R._transition_mode(self.cfg)[0], "HOLD")
        self.assertEqual(R.quarantine_state(self.cfg)[0], R._QS_DENY)
        self.assertIn("TRANSFER_HOLD", self.gate(self.lane_task()))
        (pre / "state.json").write_bytes(keep)
        self.assertEqual(R._transition_mode(self.cfg)[0], "LANE")
        self.rewrite_record(s0_slot={"state": "UNUSED"})  # slot handed out again
        self.assertEqual(R._transition_mode(self.cfg)[0], "HOLD")
        self.assertIn("TRANSFER_HOLD", self.gate(self.lane_task()))
        (self.home / R.TRANSFER_RECORD_NAME).write_bytes(s0_consumed)
        self.assertEqual(R._transition_mode(self.cfg)[0], "LANE")

