        r = self.begin()
        t = r.state["tasks"]["vp-ordinary"]
        with mock.patch.object(R, "_transition_gate_reason", side_effect=RuntimeError("injected gate fault")):  # fault injection only
            self.assertIsNone(r.next_ready())
