    def test_candidate_transfer_preflight_rejects_an_inherited_verify_pending_task(self):
        self.write_home(review="APPROVED")
        self.assertEqual(R.transfer_preflight(self.cfg, rlock_held=True, wlock_held=True)["stage"], R.TRANSFER_READY)  # control: otherwise ready
        self.mutate_state(lambda st: st["tasks"].update({"vp-old": self.verify_pending_task("vp-old")}))  # inherited from the old runner
        with self.assertRaises(R.GateError) as cm:
            R.transfer_preflight(self.cfg, rlock_held=True, wlock_held=True)
        self.assertIn("verify_pending", str(cm.exception))
        evidence = self.transition_evidence()
        self.boot()
        self.assertIsNone(self.record(), "a refused preflight must consume nothing")
        self.assertFalse(self.pre_images())
        self.assertEqual(self.transition_evidence(), evidence)

    def test_candidate_live_active_process_still_continues_a_verify_pending_task(self):
        self.write_home(review="APPROVED")
        self.run_state()
        r, _ = self.drive_to_active()
        self.assertEqual(R._transition_mode(self.cfg), ("ACTIVE", None))
        # a locked module fails the ordinary prerequisite gate, but a resumed verification has already passed it: skip preserved
        t = self.verify_pending_task("vp-live", module="MOD-005")
        self.assertIsNotNone(self.gate({**t, "stage": None}))
        r.state["tasks"]["vp-live"] = t
        self.assertIs(r.next_ready(), t)
        self.assertFalse(r.gated(t))
        with mock.patch.object(R.Runner, "settle", autospec=True) as settle:
            r.dispatch(t)
        settle.assert_called_once()
        self.assertEqual(len(self.events("verification-resumed")), 1)

    def test_candidate_crash_replay_and_stale_identity_restarts_are_denied(self):
        def crash_after_pre_image():
            self.write_home(review="APPROVED")
            self.crashed_boot("_transfer_write_pre_image", after=True)
            self.assertIsNone(self.record())
            self.assertEqual(len(self.pre_images()), 1)

        def replayed_earlier_record():
            self.write_home(review="APPROVED")
            self.boot()
            unused = self.raw(R.TRANSFER_RECORD_NAME)
            self.consume_slot()
            (self.home / R.TRANSFER_RECORD_NAME).write_bytes(unused)  # hands the spent slot out again

        def stale_attested_identity_restart_spent():
            self.write_home(review="APPROVED")
            self.boot()
            dead = subprocess.Popen([sys.executable, "-c", "pass"])
            dead.wait()
            self.rewrite_record(attested={**self.record()["attested"], "pid": dead.pid, "boot_nonce": "cd" * 16}, restart_used=True)

        for label, setup in (("crash after pre-image, before record", crash_after_pre_image),
                             ("replayed earlier-stage record", replayed_earlier_record),
                             ("stale attested PID/nonce with the one restart spent", stale_attested_identity_restart_spent)):
            with self.subTest(label):
                self.rebuild_child()
                setup()
                self.run_state()
                self.restart_denied(label)
                self.assertFalse(self.ci_log.exists() and label.startswith("crash"), label)

    def test_candidate_child_concurrent_writer_and_live_old_pid_delay_but_never_fork_the_transfer(self):
        for label in ("writer lock held elsewhere", "old runner PID still alive"):
            with self.subTest(label):
                self.rebuild_child()
                held, sleeper = None, None
                if label.startswith("writer"):
                    held = R.FileLock(R.writer_lock_path(self.home, self.repo))
                    self.assertTrue(held.acquire({"pid": os.getpid()}))
                    self.addCleanup(lambda h=held: h.fd is not None and h.release())
                else:
                    sleeper = subprocess.Popen(["sleep", "600"])
                    self.addCleanup(lambda s=sleeper: (s.kill(), s.wait()))
                    self.old_pid = sleeper.pid
                    self.write_home(review=None)
                self.run_state()
                p = self.spawn(name="delay")
                if held is not None:
                    # a foreign writer lock keeps the child out of the transfer path entirely (its tick never reaches the review
                    # step), so no refusal event is guaranteed: assert the fail-closed non-entry from lock, process and record evidence
                    self.assertTrue(self.wait_for(lambda: self.n_events("quarantine-transfer-first-boot") > 0, 60, child=p),
                                    f"{label}: {self.child_log('delay')}")
                    time.sleep(2 * R.TRANSFER_STEP_EVERY)
                    self.assertIsNone(p.poll(), f"{label}: the held child keeps running: {self.child_log('delay')}")
                    self.assertEqual(R.FileLock.probe(R.writer_lock_path(self.home, self.repo)), "held", label)
                    self.assertEqual(held.owner()["pid"], os.getpid(), label)  # still the foreign holder: no second writer took it
                    # the review step may create its static bookkeeping task under the runner home (no repository write), but its
                    # dispatch and the transition are locked and re-gated: nothing is routed, staged, consumed or observed
                    self.assertLessEqual(self.n_events("transfer-review-created"), 1, label)
                    self.assertEqual([e for e in self.events("dispatch") if e.get("task_id") == R.TRANSFER_REVIEW_ID], [], label)
                    self.assertEqual([e for e in self.events("route-evidence") if str(e.get("op_id")).startswith(f"{R.TRANSFER_REVIEW_ID}:")], [], label)
                    review = json.loads((self.home / "state.json").read_text())["tasks"].get(R.TRANSFER_REVIEW_ID)
                    self.assertTrue(review is None or (review.get("status"), review.get("attempts")) == ("QUEUED", 0), label)
                    self.assertEqual(self.events("quarantine-transfer-stage"), [], label)
                else:
                    self.assertTrue(self.wait_for(lambda: self.n_events("quarantine-transfer-refused") > 0, 120, child=p),
                                    f"{label}: {self.child_log('delay')}")
                self.assertIsNone(self.rec(), label)  # held: nothing consumed, no pre-image, no provider lookup
                self.assertFalse(list((self.home / R.TRANSFER_CHECKPOINT).glob("pre-image-*")), label)
                self.assertFalse(self.ci_log.exists(), label)
                self.assertEqual(len([e for e in self.events("dispatch") if e.get("task_id") != R.TRANSFER_REVIEW_ID]), 0, label)
                if sleeper is not None:
                    self.assertIsNone(sleeper.poll(), "the runner never touches the live old process")
                    sleeper.kill()
                    sleeper.wait()
                else:
                    held.release()
                # a later safe state lets the SAME child consume exactly once (the refusal consumed nothing)
                self.assertTrue(self.wait_for(lambda: self.stage() == "S0_REBIND", 120, child=p), f"{label}: {self.child_log('delay')}")
                self.assertEqual(self.stage_events(), ["TRANSFER_CONSUMED", "S0_REBIND"], label)
                self.assertEqual(len(self.pre_images()), 1, label)
                if held is not None:  # exactly one review, dispatched once, then exactly one transition
                    self.assertEqual(self.n_events("transfer-review-created"), 1, label)
                    self.assertEqual(len([e for e in self.events("dispatch") if e.get("task_id") == R.TRANSFER_REVIEW_ID]), 1, label)
                    self.assertEqual(len(self.events("quarantine-transfer-first-boot")), 1, label)
                self.stop(p)

